OUTPUT_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sessions.jsonl")


def parse_timestamp(ts: str) -> datetime:
    """Parse an ISO 8601 timestamp string into an aware datetime in UTC."""
    # Handle the trailing 'Z' (Zulu) which Python <3.11 doesn't understand natively.
    if ts.endswith("Z"):
        ts = ts[:-1] + "+00:00"
    dt = datetime.fromisoformat(ts)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def format_timestamp(dt: datetime) -> str:
    """Format a datetime back into an ISO 8601 string with 'Z' suffix."""
    # Convert to UTC and format with 'Z' for consistency with input.
    dt_utc = dt.astimezone(timezone.utc)
    # Use isoformat and replace +00:00 with Z
    s = dt_utc.isoformat()
    if s.endswith("+00:00"):
        s = s[:-6] + "Z"
    return s


class JSONLSource(FixedPartitionedSource[str, int]):
