    @override
    def close(self) -> None:
        self._fh.close()


def build_flow() -> Dataflow:
    flow = Dataflow("sessionization")

    # Read raw JSON lines from the input file.
    raw = op.input("in", flow, JSONLSource(INPUT_PATH))

    # Parse JSON lines into dicts and add the parsed datetime for the clock.
    events = op.map("parse", raw, lambda line: json.loads(line))

    # Group events by user_id, attaching a parsed timestamp to each event.
    keyed = op.key_on("by_user", events, lambda e: e["user_id"])

    # EventTime clock: extract datetime from each event's timestamp field.
    clock = EventClock(lambda e: parse_timestamp(e["timestamp"]), wait_for_system_duration=timedelta(seconds=1))

    # Session window with 30 minute inactivity gap.
    windower = SessionWindower(gap=timedelta(minutes=30))

    # Collect events in each session.
    windows = collect_window("session", keyed, clock, windower)

    # Map each collected window into a session summary dict.
    # `windows.down` is a KeyedStream[Tuple[int, List[event]]] keyed by (user_id, window_id).
    summaries = op.map_value("summarize", windows.down, lambda events: {
        "session_start": format_timestamp(parse_timestamp(min(e["timestamp"] for e in events)["timestamp"]) if False else min(parse_timestamp(e["timestamp"]) for e in events)),
        "session_end": format_timestamp(max(parse_timestamp(e["timestamp"]) for e in events)),
        "event_count": len(events),
    })

    # The down stream is keyed by (user_id, window_id). We need to flatten back to user_id.
    # summaries is KeyedStream[(user_id, window_id), summary_dict]
    flat = op.map("flatten", summaries, lambda kv: (kv[0][0], kv[1]))

    # Output the summary for each session.
    out = op.map("format_output", flat, lambda kv: {
        "user_id": kv[0],
        "session_start": kv[1]["session_start"],
        "session_end": kv[1]["session_end"],
        "event_count": kv[1]["event_count"],
    })

    op.output("out", out, JSONLSink(OUTPUT_PATH))
    return flow


if __name__ == "__main__":
    flow = build_flow()
    run_main(flow)
